// Extract audio file information
const audioFile = $input.item.binary?.data;
const audioUrl = $input.item.json.audio_url;
const options = $input.item.json.options || {};

if (!audioFile && !audioUrl) {
  throw new Error('No audio file or URL provided');
}

// Validate audio format
const supportedFormats = ['mp3', 'mp4', 'mpeg', 'mpga', 'm4a', 'wav', 'webm', 'flac', 'ogg'];
const fileName = audioFile?.fileName || audioUrl?.split('/').pop() || '';
const fileExtension = fileName.split('.').pop().toLowerCase();

if (!supportedFormats.includes(fileExtension)) {
  throw new Error(`Unsupported audio format: ${fileExtension}. Supported: ${supportedFormats.join(', ')}`);
}

// Extract transcription options
const transcriptionOptions = {
  request_id: `audio_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp: new Date().toISOString(),
  audio_source: audioFile ? 'upload' : 'url',
  file_name: fileName,
  file_extension: fileExtension,
  language: options.language || 'auto',
  speaker_labels: options.speaker_labels !== false,
  word_timestamps: options.word_timestamps !== false,
  translate_to_english: options.translate_to_english === true,
  generate_subtitles: options.generate_subtitles !== false,
  providers: options.providers || ['whisper', 'google', 'assemblyai']
};

return {
  json: transcriptionOptions,
  binary: audioFile ? { data: audioFile } : undefined
};

// Aggregate all transcription results
const items = $input.all();

// Get base data
const baseData = items.find(item => item.json.request_id)?.json;

// Extract Whisper transcription
const whisperResult = items.find(item => item.json.text && item.json.duration);
const whisperData = whisperResult ? {
  provider: 'openai_whisper',
  text: whisperResult.json.text,
  language: whisperResult.json.language,
  duration: whisperResult.json.duration,
  segments: whisperResult.json.segments?.map(seg => ({
    start: seg.start,
    end: seg.end,
    text: seg.text
  })) || [],
  words: whisperResult.json.words?.map(w => ({
    word: w.word,
    start: w.start,
    end: w.end
  })) || []
} : null;

// Extract Google Speech-to-Text
const googleResult = items.find(item => item.json.results);
const googleData = googleResult ? {
  provider: 'google_speech',
  text: googleResult.json.results
    ?.map(r => r.alternatives?.[0]?.transcript)
    .filter(Boolean)
    .join(' ') || '',
  confidence: googleResult.json.results?.[0]?.alternatives?.[0]?.confidence || 0,
  words: googleResult.json.results?.[0]?.alternatives?.[0]?.words?.map(w => ({
    word: w.word,
    start: parseFloat(w.startTime?.replace('s', '')) || 0,
    end: parseFloat(w.endTime?.replace('s', '')) || 0,
    speaker: w.speakerTag || null
  })) || []
} : null;

// Extract AssemblyAI
const assemblyaiResult = items.find(item => item.json.status === 'completed' && item.json.utterances);
const assemblyaiData = assemblyaiResult ? {
  provider: 'assemblyai',
  text: assemblyaiResult.json.text,
  confidence: assemblyaiResult.json.confidence,
  language_code: assemblyaiResult.json.language_code,
  utterances: assemblyaiResult.json.utterances?.map(u => ({
    speaker: u.speaker,
    start: u.start,
    end: u.end,
    text: u.text,
    confidence: u.confidence
  })) || [],
  words: assemblyaiResult.json.words?.map(w => ({
    word: w.text,
    start: w.start / 1000,
    end: w.end / 1000,
    confidence: w.confidence,
    speaker: w.speaker || null
  })) || []
} : null;

// Combine transcriptions
const transcriptions = [whisperData, googleData, assemblyaiData].filter(Boolean);

// Calculate word error rate (WER) approximation by comparing texts
function calculateSimilarity(text1, text2) {
  const words1 = text1.toLowerCase().split(/\s+/);
  const words2 = text2.toLowerCase().split(/\s+/);
  const maxLength = Math.max(words1.length, words2.length);
  if (maxLength === 0) return 1;

  const commonWords = words1.filter(w => words2.includes(w)).length;
  return commonWords / maxLength;
}

// Find best transcription (highest confidence or most complete)
const bestTranscription = transcriptions.reduce((best, current) => {
  const currentScore = (current.confidence || 0.8) * (current.text?.length || 0);
  const bestScore = (best.confidence || 0.8) * (best.text?.length || 0);
  return currentScore > bestScore ? current : best;
}, transcriptions[0]);

// Generate SRT subtitles from best transcription
function generateSRT(segments) {
  if (!segments || segments.length === 0) return '';

  return segments.map((seg, i) => {
    const formatTime = (seconds) => {
      const hrs = Math.floor(seconds / 3600);
      const mins = Math.floor((seconds % 3600) / 60);
      const secs = Math.floor(seconds % 60);
      const ms = Math.floor((seconds % 1) * 1000);
      return `${String(hrs).padStart(2, '0')}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')},${String(ms).padStart(3, '0')}`;
    };

    return `${i + 1}\n${formatTime(seg.start)} --> ${formatTime(seg.end)}\n${seg.text}\n`;
  }).join('\n');
}

const srtContent = generateSRT(
  whisperData?.segments || 
  (googleData?.words && googleData.words.length > 0 ? 
    [{ start: googleData.words[0].start, end: googleData.words[googleData.words.length-1].end, text: googleData.text }] : [])
);

// Generate VTT subtitles
const vttContent = srtContent ? `WEBVTT\n\n${srtContent.replace(/,/g, '.')}` : '';

// Build final result
const result = {
  request_id: baseData?.request_id,
  timestamp: baseData?.timestamp,
  audio_info: {
    file_name: baseData?.file_name,
    format: baseData?.file_extension,
    duration: whisperData?.duration || null
  },
  transcription: {
    text: bestTranscription?.text || '',
    language: whisperData?.language || assemblyaiData?.language_code || baseData?.language,
    confidence: bestTranscription?.confidence || null,
    provider: bestTranscription?.provider
  },
  providers_comparison: {
    providers_used: transcriptions.map(t => t.provider),
    text_similarity: transcriptions.length >= 2 ? 
      calculateSimilarity(transcriptions[0].text, transcriptions[1].text).toFixed(3) : null,
    results: transcriptions
  },
  speaker_diarization: {
    enabled: baseData?.speaker_labels,
    speakers_detected: assemblyaiData?.utterances?.length > 0 ? 
      [...new Set(assemblyaiData.utterances.map(u => u.speaker))].length : null,
    utterances: assemblyaiData?.utterances || []
  },
  word_timestamps: {
    enabled: baseData?.word_timestamps,
    total_words: bestTranscription?.words?.length || 0,
    words: bestTranscription?.words?.slice(0, 100) || []
  },
  subtitles: {
    srt: srtContent,
    vtt: vttContent
  },
  metadata: {
    processing_time_ms: Date.now() - new Date(baseData?.timestamp).getTime(),
    providers_count: transcriptions.length
  }
};

return {
  json: result
};
